[{"id": "dXmwP8ekIeyE54bTxqMaxL4reazwdiBy", "function": {"index": 0, "name": "write_file", "arguments": {"path": "config_reader.py", "content": "def read_settings(text):
    lines = text.splitlines()
    settings = {}
    seen_keys = set()
    for line in lines:
        stripped = line.strip()
        if not stripped or stripped.startswith('#'):
            continue
        if '=' not in stripped:
            raise ValueError(f"Malformed line: {stripped}")
        # Split on first '='
        key, val = stripped.split('=', 1)
        key = key.strip()
        val = val.strip()
        if key in seen_keys:
            raise ValueError(f"Duplicate key: {key}")
        seen_keys.add(key)
        settings[key] = val
    # Check required keys
    if 'endpoint' not in settings:
        raise ValueError("Missing required key: endpoint")
    if 'enabled' not in settings:
        raise ValueError("Missing required key: enabled")
    # Convert enabled to boolean
    enabled_raw = settings['enabled']
    if enabled_raw.lower() == 'true':
        enabled_bool = True
    elif enabled_raw.lower() == 'false':
        enabled_bool = False
    else:
        raise ValueError(f"Invalid value for enabled: {enabled_raw}")
    return {
        'endpoint': settings['endpoint'],
        'enabled': enabled_bool
    }"}}}]
